import React from 'react';
import '../styles/Home.css';
import welcomeImg from '../images/Professora.svg';

export default function Home() {
  return (
    <div className="home-container">
      <section className="welcome-card">
        <div className="welcome-text">
          <h1>Bem vindo professor!</h1>
          <p>
            Explore nossa plataforma de atividades desplugadas baseadas na BNCC 
            e leve o pensamento computacional para sua sala de aula de forma prática.
          </p>
        </div>
        <div className="welcome-image">
          <img src={welcomeImg} alt="Ilustração de boas-vindas" />
        </div>
      </section>

      {/* Outros conteúdos rápidos da Home podem vir aqui */}
    </div>
  );
}