import { Link } from "react-router-dom";

export default function ActivityCard({ atividade }) {
  return (
    <div className="card">
      <h3>{atividade.titulo || "Sem título"}</h3>
      <p>{atividade.descricao || "Sem descrição"}</p>
      
      <div className="card-info">
        <span><strong>Ano:</strong> {atividade.ano || "N/A"}</span>
        <span><strong>Eixo:</strong> {atividade.eixo_bncc || "N/A"}</span>
      </div>

      <Link to={`/atividade/${atividade.id}`} className="btn-detalhes">
        Ver detalhes
      </Link>
    </div>
  );
}