import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import '../styles/Sidebar.css';
import logo from '../images/logo.svg'; 

export default function Sidebar() {
  return (
    <aside className="sidebar">
      <div className="logo-container">
        {/* Substituímos a div vazia pela imagem do logo */}
        <img src={logo} alt="Logo" className="logo-img" />
      </div>
      
      <nav className="menu-options">
        <ul>
          <Link to="/" style={{ textDecoration: 'none' }}>
            <li className={useLocation().pathname === "/" ? "active" : ""}>
              <span className="icon">🏠</span> Inicio
            </li>
          </Link>
          <Link to="/atividades" style={{ textDecoration: 'none' }}>
            <li className={useLocation().pathname === "/atividades" ? "active" : ""}>
              <span className="icon">📊</span> Atividades
            </li>
          </Link>
        </ul>
      </nav>

      <div className="sidebar-footer">
        <div className="footer-card">
          <p>Dúvidas?</p>
          <button>Acessar FAQ</button>
        </div>
      </div>
    </aside>
  );
}